12	// DEVDESK-709, S-01b: a signal goes only to the process that was listed. These
13	// are the pure parts: the Identity value, its two errors, the parsing of the
14	// operating system's creation stamps and the decision taken at the signal.
15	
16	// ── The value ────────────────────────────────────────────────────────────────
17	
18	// The zero value is "unknown", so a caller that forgets the identity cannot
19	// send a signal (criterion 5).
20	func TestTheZeroIdentityIsNotVerifiable(t *testing.T) {
21		if (Identity{}).Verifiable() {
22			t.Error("the zero Identity is verifiable: a forgotten identity would pass for a known one")
23		}
24		if !IdentityForTest(7).Verifiable() {
25			t.Error("IdentityForTest(7) is not verifiable")
26		}
27		if !DeferredIdentityForTest(fakeEpoch).Verifiable() {
28			t.Error("a deferred identity is not verifiable: the row would be greyed although it can be read at confirmation")
29		}
30	}
31	
32	// Identities are compared with == by the tests and by the UI fixtures, so two
33	// reads of the same stamp must be equal and two different stamps must not.
34	func TestIdentityIsComparable(t *testing.T) {
35		if IdentityForTest(7) != IdentityForTest(7) {
36			t.Error("two identities built from the same stamp differ")
37		}
38		if IdentityForTest(7) == IdentityForTest(8) {
39			t.Error("two identities built from different stamps are equal")
40		}
41		if IdentityForTest(7) == (Identity{}) {
42			t.Error("a known identity equals the unknown one")
43		}
44		if IdentityForTest(7) == DeferredIdentityForTest(fakeEpoch) {
45			t.Error("a known identity equals a deferred one")
46		}
47	}
