49	func TestConflicts(t *testing.T) {
50		cases := []struct {
51			name string
52			a, b Identity
53			want bool
54		}{
55			{"same stamp", IdentityForTest(7), IdentityForTest(7), false},
56			{"different stamps", IdentityForTest(7), IdentityForTest(8), true},
57			{"different stamps, the other way", IdentityForTest(8), IdentityForTest(7), true},
58			{"known and deferred", IdentityForTest(7), DeferredIdentityForTest(fakeEpoch), false},
59			{"deferred and known", DeferredIdentityForTest(fakeEpoch), IdentityForTest(7), false},
60			{"known and unknown", IdentityForTest(7), Identity{}, false},
61			{"unknown and known", Identity{}, IdentityForTest(7), false},
62			{"two unknown", Identity{}, Identity{}, false},
63			{"two deferred", DeferredIdentityForTest(fakeEpoch), DeferredIdentityForTest(fakeEpoch.Add(time.Hour)), false},
64		}
65		for _, tc := range cases {
66			t.Run(tc.name, func(t *testing.T) {
67				if got := tc.a.Conflicts(tc.b); got != tc.want {
68					t.Errorf("Conflicts = %v, want %v", got, tc.want)
69				}
70			})
71		}
72	}
