140	func TestTimevalStamp(t *testing.T) {
141		cases := []struct {
142			sec  int64
143			usec int32
144			want uint64
145		}{
146			{1, 2, 1000002},
147			{0, 0, 0},
148			{0, 999999, 999999},
149			{1700000000, 123456, 1700000000123456},
150		}
151		for _, tc := range cases {
152			if got := timevalStamp(tc.sec, tc.usec); got != tc.want {
153				t.Errorf("timevalStamp(%d, %d) = %d, want %d", tc.sec, tc.usec, got, tc.want)
154			}
155		}
156	}
