158	func TestFiletimeUnixNano(t *testing.T) {
159		cases := []struct {
160			name string
161			raw  uint64
162			want int64
163		}{
164			{"the Unix epoch", 116444736000000000, 0},
165			{"one second after it", 116444736000000000 + 10_000_000, 1_000_000_000},
166			{"100 ns after it", 116444736000000000 + 1, 100},
167			{"a known instant", filetimeOf(fakeEpoch), fakeEpoch.UnixNano()},
168		}
169		for _, tc := range cases {
170			t.Run(tc.name, func(t *testing.T) {
171				if got := filetimeUnixNano(tc.raw); got != tc.want {
172					t.Errorf("filetimeUnixNano(%d) = %d, want %d", tc.raw, got, tc.want)
173				}
174			})
175		}
176	}
