207	func TestVerdictAtSignal(t *testing.T) {
208		const pid = 4242
209		wrappedGone := fmt.Errorf("reading /proc/4242/stat: %w", os.ErrProcessDone)
210	
211		t.Run("the same stamp sends", func(t *testing.T) {
212			if err := verdictAtSignal(pid, IdentityForTest(7), 7, nil); err != nil {
213				t.Errorf("verdictAtSignal = %v, want nil", err)
214			}
215		})
216	
217		t.Run("another stamp refuses with an IdentityChangedError", func(t *testing.T) {
218			err := verdictAtSignal(pid, IdentityForTest(7), 8, nil)
219			var changed *IdentityChangedError
220			if !errors.As(err, &changed) {
221				t.Fatalf("verdictAtSignal = %v (%T), want an *IdentityChangedError", err, err)
222			}
223			if changed.PID != pid {
224				t.Errorf("PID = %d, want %d", changed.PID, pid)
225			}
226		})
227	
228		t.Run("a process that is gone is reported as gone", func(t *testing.T) {
229			for _, readErr := range []error{os.ErrProcessDone, wrappedGone} {
230				err := verdictAtSignal(pid, IdentityForTest(7), 0, readErr)
231				if !errors.Is(err, os.ErrProcessDone) {
232					t.Errorf("verdictAtSignal(%v) = %v, want errors.Is os.ErrProcessDone", readErr, err)
233				}
234				var changed *IdentityChangedError
235				var unverifiable *UnverifiableError
236				if errors.As(err, &changed) || errors.As(err, &unverifiable) {
237					t.Errorf("a gone process was reported as %T: it must read as 'no longer running'", err)
238				}
239				if err != nil && !strings.Contains(err.Error(), "4242") {
240					t.Errorf("verdictAtSignal = %q, want it to name the PID", err.Error())
241				}
242			}
243		})
244	
245		t.Run("any other read failure is unverifiable, and the cause stays out of errors.Is", func(t *testing.T) {
246			for _, readErr := range []error{os.ErrPermission, errors.New("short read"), errors.ErrUnsupported} {
247				err := verdictAtSignal(pid, IdentityForTest(7), 7, readErr)
248				var unverifiable *UnverifiableError
249				if !errors.As(err, &unverifiable) {
250					t.Fatalf("verdictAtSignal(%v) = %v (%T), want an *UnverifiableError", readErr, err, err)
251				}
252				if unverifiable.PID != pid {
253					t.Errorf("PID = %d, want %d", unverifiable.PID, pid)
254				}
255				if !errors.Is(unverifiable.Cause, readErr) {
256					t.Errorf("Cause = %v, want %v (kept for the log)", unverifiable.Cause, readErr)
257				}
258				if errors.Is(err, readErr) {
259					t.Errorf("errors.Is(%v, %v) = true: the cause must not leak through Unwrap, or 'refused by the system' would be shown for a refusal that is DevDesk's own", err, readErr)
260				}
261			}
262		})
263	
264		t.Run("a read failure wins over a matching stamp", func(t *testing.T) {
265			// A read error leaves the stamp at its zero value; a want of zero must not
266			// be taken for "equal".
267			err := verdictAtSignal(pid, IdentityForTest(0), 0, os.ErrPermission)
268			if err == nil {
269				t.Error("verdictAtSignal = nil: a failed read let a signal through")
270			}
271		})
272	}
