455	// TestKillOfAnExitedChildSendsNothing: the listed process is gone. Either the
456	// PID is free (no process) or it was taken by another process (a different
457	// identity); a signal is never sent, and Kill never reports success.
458	func TestKillOfAnExitedChildSendsNothing(t *testing.T) {
459		if runtime.GOOS != "linux" {
460			t.Skip("the real-child proof is run on Linux")
461		}
462		child := startHelperChild(t)
463		listed := child.identityOf(t)
464	
465		_ = child.cmd.Process.Kill() // the test's own child, ended by the test
466		select {
467		case <-child.done:
468		case <-time.After(10 * time.Second):
469			t.Fatalf("the helper process %d did not exit", child.pid)
470		}
471	
472		allowRealSignals(t)
473		err := Kill(strconv.Itoa(child.pid), listed)
474	
475		var changed *IdentityChangedError
476		if err == nil {
477			t.Fatal("Kill of an exited process returned nil")
478		}
479		if !errors.Is(err, os.ErrProcessDone) && !errors.As(err, &changed) {
480			t.Errorf("Kill = %v (%T), want errors.Is os.ErrProcessDone or an *IdentityChangedError", err, err)
481		}
482	}
