104	// Criteria 3 and 6: what the signal point returns stays reachable through Kill's
105	// wrapping, so the UI can tell a refusal of the system from DevDesk's own.
106	func TestKillKeepsTheOSErrorReadable(t *testing.T) {
107		t.Run("sentinels, bare and wrapped by the opening of the process", func(t *testing.T) {
108			causes := []error{
109				os.ErrPermission,
110				os.ErrProcessDone,
111				fmt.Errorf("opening the process: %w", os.ErrPermission),
112				fmt.Errorf("process 4242: %w", os.ErrProcessDone),
113			}
114			for _, cause := range causes {
115				fake := useFakeOS(t, 100, 99, "linux")
116				fake.killErr = cause
117	
118				err := Kill("4242", IdentityForTest(1))
119	
120				sentinel := os.ErrPermission
121				if errors.Is(cause, os.ErrProcessDone) {
122					sentinel = os.ErrProcessDone
123				}
124				if !errors.Is(err, sentinel) {
125					t.Errorf("Kill with %q: errors.Is(%v, %v) = false: the cause was not wrapped with %%w", cause, err, sentinel)
126				}
127				var unverifiable *UnverifiableError
128				var changed *IdentityChangedError
129				if errors.As(err, &unverifiable) || errors.As(err, &changed) {
130					t.Errorf("Kill turned %q into %T", cause, err)
131				}
132			}
133		})
134	
135		t.Run("DevDesk's own refusals", func(t *testing.T) {
136			fake := useFakeOS(t, 100, 99, "linux")
137	
138			fake.killErr = &IdentityChangedError{PID: 4242}
139			var changed *IdentityChangedError
140			if err := Kill("4242", IdentityForTest(1)); !errors.As(err, &changed) {
141				t.Errorf("Kill = %v (%T), want it to carry the *IdentityChangedError", err, err)
142			}
143	
144			fake.killErr = &UnverifiableError{PID: 4242, Cause: os.ErrPermission}
145			var unverifiable *UnverifiableError
146			err := Kill("4242", IdentityForTest(1))
147			if !errors.As(err, &unverifiable) {
148				t.Fatalf("Kill = %v (%T), want it to carry the *UnverifiableError", err, err)
149			}
150			if errors.Is(err, os.ErrPermission) {
151				t.Error("the permission cause of an UnverifiableError leaked through Kill")
152			}
153		})
154	}
