170			{
171				name:   "a known identity is returned as it is, with no read",
172				listed: func(*fakeOS) Identity { return IdentityForTest(9) },
173				want:   func(*fakeOS) Identity { return IdentityForTest(9) },
174			},
175			{
176				name:   "an unknown identity is unverifiable, with no read",
