179					var u *UnverifiableError
180					if !errors.As(err, &u) {
181						t.Errorf("err = %v (%T), want an *UnverifiableError", err, err)
182					}
183				},
184			},
185			{
186				name:      "deferred, born a second before the listing: the read becomes the identity",
187				listed:    deferred,
188				read:      func(f *fakeOS) { f.ids[4412] = filetimeOf(f.clock.Add(-time.Second)) },
189				want:      func(f *fakeOS) Identity { return IdentityForTest(filetimeOf(f.clock.Add(-time.Second))) },
190				wantReads: 1,
191			},
192			{
193				name:   "deferred, born a second after the listing: not the process that was listed",
