380	// logPidfd tells the PR which kernel the guarantee was run on: with a pidfd the
381	// comparison is made with the process held, without one a residual window
382	// remains (documented).
383	func logPidfd(t *testing.T, pid int) {
384		t.Helper()
385		p, err := os.FindProcess(pid)
386		if err != nil {
387			t.Logf("os.FindProcess(%d): %v", pid, err)
388			return
389		}
390		defer p.Release() //nolint:errcheck // the only effect is releasing a descriptor
391		if err := p.WithHandle(func(uintptr) {}); err != nil {
392			t.Logf("no process handle on this kernel (%v): the comparison has a residual window", err)
393			return
394		}
395		t.Logf("the process is held by a handle (pidfd): the comparison is made with the process held")
396	}
