398	// TestKillEndsARealChildProcess sends a real signal to a child the test started
399	// itself, with the identity that child really has: a matching identity must not
400	// get in the way.
401	func TestKillEndsARealChildProcess(t *testing.T) {
402		child := startHelperChild(t)
403		listed := child.identityOf(t)
404		logPidfd(t, child.pid)
405	
406		allowRealSignals(t)
407		if err := Kill(strconv.Itoa(child.pid), listed); err != nil {
408			t.Fatalf("Kill(%d) = %v, want nil", child.pid, err)
409		}
410	
411		select {
412		case <-child.done:
413		case <-time.After(10 * time.Second):
414			t.Fatalf("the helper process %d was still running 10 s after Kill", child.pid)
415		}
416		if child.waitErr == nil {
417			t.Error("the helper process exited successfully: it was not ended by the signal")
418		}
419		if child.cmd.ProcessState == nil || child.cmd.ProcessState.Success() {
420			t.Errorf("ProcessState = %v, want an unsuccessful exit", child.cmd.ProcessState)
421		}
422	}
