424	// TestKillSparesARealChildWhoseIdentityDiffers is criterion 2 on a real process:
425	// the PID is held by a live process whose identity is not the one that was
426	// listed, and no signal reaches it.
427	func TestKillSparesARealChildWhoseIdentityDiffers(t *testing.T) {
428		if runtime.GOOS != "linux" {
429			t.Skip("the real-child proof is run on Linux, where the process is held by a pidfd")
430		}
431		child := startHelperChild(t)
432		listed := child.identityOf(t)
433		other := IdentityForTest(listed.raw + 1)
434		logPidfd(t, child.pid)
435	
436		allowRealSignals(t)
437		err := Kill(strconv.Itoa(child.pid), other)
438	
439		var changed *IdentityChangedError
440		if !errors.As(err, &changed) {
441			t.Fatalf("Kill with another identity = %v (%T), want an *IdentityChangedError", err, err)
442		}
443		if changed.PID != child.pid {
444			t.Errorf("PID = %d, want %d", changed.PID, child.pid)
445		}
446		time.Sleep(300 * time.Millisecond)
447		if !child.running() {
448			t.Fatalf("the helper process %d ended (%v): a signal reached a process whose identity differed", child.pid, child.waitErr)
449		}
450		if child.cmd.ProcessState != nil {
451			t.Errorf("ProcessState = %v, want none: the child must still be running", child.cmd.ProcessState)
452		}
